17	package org.springframework.samples.petclinic.util;
18	
19	import java.time.LocalDate;
20	
21	/**
22	 * Derivation of an owner's {@code memberId}, the single unified identity every other owner value is
23	 * now built from. It replaces the previously separate {@code customerCode} and {@code
24	 * membershipNumber}. Kept separate from the owner controller and the {@code Owner} model so the rule
25	 * lives in one place, as pure functions with no web or persistence dependencies. Mirrors
26	 * {@link LocalityResolver} (which supplies the region), {@link FiscalYear} (the fiscal year) and
27	 * {@link LuhnCheckDigit} (the check digit).
28	 *
29	 * <p>The id is {@code '<REGION><FY><HASH8><CHK>'} (no separators): REGION is the region derived from
30	 * the owner's postcode (see {@link LocalityResolver#resolveFromPostcode}); FY is the two-digit fiscal
31	 * year the owner's registration date falls in (see {@link FiscalYear#yearOf}); HASH8 is the first
32	 * eight upper-case hexadecimal characters of the SHA-256 digest of the owner's normalized telephone
33	 * concatenated with the last name (the region-and-hash identity's hash component); and CHK is a
34	 * single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}. On a collision
35	 * with an existing owner's id, {@code '-<n>'} is appended (handled by the service), so the REGION and
36	 * FY components are always the leading run of letters followed by the two fiscal-year digits.
37	 */
38	public abstract class MemberId {
39	
40	    /** Number of leading hex characters of the SHA-256 digest kept as the HASH8 component. */
41	    private static final int HASH_LENGTH = 8;
42	
43	    /** Number of digits in the fiscal-year (FY) component. */
44	    private static final int FY_LENGTH = 2;
45	
46	    /**
47	     * Build a member id {@code '<REGION><FY><HASH8><CHK>'} from an owner's region, registration date,
48	     * telephone and last name.
49	     *
50	     * @param region           the region code (e.g. {@code NSW}, or {@code UNKNOWN})
51	     * @param registrationDate the owner's business-day-adjusted registration date (must not be null)
52	     * @param telephone        the owner's normalized telephone, or null
53	     * @param lastName         the owner's last name, or null
54	     * @return the member id
55	     */
56	    public static String of(String region, LocalDate registrationDate, String telephone, String lastName) {
57	        String base = region + fyDigits(registrationDate) + hash8(telephone, lastName);
58	        return base + LuhnCheckDigit.of(base);
59	    }
60	
61	    /**
62	     * The HASH8 component alone: the first eight upper-case hex characters of the SHA-256 digest of the
63	     * owner's normalized telephone concatenated with the last name, each part treated as the empty
64	     * string when absent. This is the region-and-hash identity's hash component.
65	     *
66	     * @param telephone the owner's normalized telephone, or null
67	     * @param lastName  the owner's last name, or null
68	     * @return the eight-character upper-case hex HASH8
69	     */
70	    public static String hash8(String telephone, String lastName) {
71	        String telephonePart = telephone == null ? "" : telephone;
72	        String lastNamePart = lastName == null ? "" : lastName;
73	        return Sha256.hex(telephonePart + lastNamePart).substring(0, HASH_LENGTH).toUpperCase();
74	    }
75	
76	    /**
77	     * The two-digit fiscal-year (FY) component for a date: the last two digits of the fiscal year the
78	     * date falls in, zero-padded (see {@link FiscalYear#yearOf}).
79	     */
80	    private static String fyDigits(LocalDate date) {
81	        return String.format("%02d", FiscalYear.yearOf(date) % 100);
82	    }
83	
84	    /**
85	     * The region (the leading run of letters) of a member id, or {@code null} when the id is
86	     * {@code null}. This is how the owner's locality is now derived from its identity. The region is
87	     * followed by the two fiscal-year digits, so it ends at the first digit.
88	     *
89	     * @param memberId a member id, or null
90	     * @return the region component, or null
91	     */
92	    public static String region(String memberId) {
93	        if (memberId == null) {
94	            return null;
95	        }
96	        int i = 0;
97	        while (i < memberId.length() && !Character.isDigit(memberId.charAt(i))) {
98	            i++;
99	        }
100	        return memberId.substring(0, i);
101	    }
102	
103	    /**
104	     * The owner's {@code FY<YY>} fiscal-year label derived from a member id, or {@code null} when the id
105	     * is {@code null} or too short to carry the FY component. {@code YY} is the two fiscal-year digits
106	     * that follow the {@linkplain #region region} in the id.
107	     *
108	     * @param memberId a member id, or null
109	     * @return the fiscal-year label (e.g. {@code FY27}), or null
110	     */
111	    public static String fiscalYearLabel(String memberId) {
112	        if (memberId == null) {
113	            return null;
114	        }
115	        int regionLength = region(memberId).length();
116	        if (memberId.length() < regionLength + FY_LENGTH) {
117	            return null;
118	        }
119	        return "FY" + memberId.substring(regionLength, regionLength + FY_LENGTH);
120	    }
121	
122	}
