72	 */
73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
81	     * carrying the new owner's id, member id and registration date.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Source of the {@code seq} carried by each {@link OwnerCreatedEvent}: a monotonically increasing
87	     * counter bumped once per successful create, so every emitted event carries a strictly larger
88	     * sequence number than the create before it.
89	     */
90	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
91	
92	    /**
93	     * Maximum number of owners a single city may hold. A create whose city already contains this many
94	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
95	     */
96	    private static final int MAX_OWNERS_PER_CITY = 50;
97	
98	    /**
99	     * The number of owners a city must already hold before a create made for that city is flagged with
100	     * {@code capacityWarning}. Once the city holds at least this many owners (but still fewer than
101	     * {@link #MAX_OWNERS_PER_CITY}, so the create is not rejected), the new owner's {@code
102	     * capacityWarning} is {@code true}, signalling the city is approaching its capacity limit.
103	     */
104	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
105	
106	    /**
107	     * Maximum number of owners that may be registered in a single day. A create made once this many
108	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
109	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
110	     */
111	    private static final int MAX_OWNERS_PER_DAY = 100;
112	
113	    /**
114	     * The number of owners that must already carry a given day's {@code registrationDate} before a
115	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
116	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
117	     */
118	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
119	
120	    /**
121	     * Request header carrying the client-supplied idempotency key for a create. When a create repeats
122	     * with a key already seen, the originally created owner is returned with {@code 200 OK} instead of
123	     * creating a duplicate (see {@link #addOwner}).
124	     */
125	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
126	
127	    /**
128	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that create originally produced,
129	     * so a repeated create carrying the same key replays that owner rather than creating a duplicate.
130	     */
131	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
132	
133	    private final ClinicService clinicService;
134	
135	    private final OwnerMapper ownerMapper;
136	
137	    private final PetMapper petMapper;
138	
139	    private final VisitMapper visitMapper;
140	
141	    public OwnerRestControllerV1(ClinicService clinicService,
142	                                 OwnerMapper ownerMapper,
143	                                 PetMapper petMapper,
144	                                 VisitMapper visitMapper) {
145	        this.clinicService = clinicService;
146	        this.ownerMapper = ownerMapper;
147	        this.petMapper = petMapper;
148	        this.visitMapper = visitMapper;
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
154	        Collection<Owner> owners;
155	        if (lastName != null) {
156	            owners = this.clinicService.findOwnerByLastName(lastName);
157	        } else {
158	            owners = this.clinicService.findAllOwners();
159	        }
160	        if (owners.isEmpty()) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
179	        String idempotencyKey = idempotencyKey();
180	        if (idempotencyKey != null) {
181	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
182	            if (existingId != null) {
183	                Owner existing = this.clinicService.findOwnerById(existingId);
184	                if (existing != null) {
185	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
186	                }
187	            }
188	        }
189	        normalizeAddress(ownerFieldsDto);
190	        rejectBlankOwnerFields(ownerFieldsDto);
191	        rejectInvalidPostcode(ownerFieldsDto);
192	        normalizeTelephone(ownerFieldsDto);
193	        normalizeEmail(ownerFieldsDto);
194	        String householdId = householdIdFor(ownerFieldsDto);
195	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
196	        rejectDuplicateIdentity(ownerFieldsDto);
197	        long ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
198	        rejectCityAtCapacity(ownerFieldsDto.getCity(), ownersInCity);
199	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
200	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
201	        long registeredThatDay = countRegisteredOn(registrationDate);
202	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
203	        HttpHeaders headers = new HttpHeaders();
204	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
205	        owner.setRegistrationDate(registrationDate);
206	        owner.setHouseholdId(householdId);
207	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
208	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
209	        owner.setCapacityWarning(ownersInCity >= CAPACITY_WARNING_THRESHOLD);
210	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
211	        owner.setMembershipLevel(cappedMembershipLevel(owner));
212	        markPossibleDuplicate(owner, sharesHousehold);
213	        this.clinicService.saveOwner(owner);
214	        if (idempotencyKey != null) {
215	            this.idempotentCreates.put(idempotencyKey, owner.getId());
216	        }
217	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
218	        emitOwnerCreatedAudit(owner, ownerDto);
219	        headers.setLocation(UriComponentsBuilder.newInstance()
220	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
221	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
222	    }
