323	    /**
324	     * Emits the audit trail for a freshly created owner: the human-readable {@code AUDIT} line and the
325	     * structured {@link OwnerCreatedEvent}, in that order. Both carry the owner's primary identifier,
326	     * the unified {@code memberId} returned by {@link #primaryIdentifier}, so keeping the two emissions
327	     * together in one place lets the audit trail's view of the owner's identity change in a single spot.
328	     * The event's {@code seq} is bumped exactly once here, so every emitted event carries a strictly
329	     * larger sequence number than the create before it.
330	     *
331	     * @param owner    the freshly created and persisted owner, already stamped with its identity
332	     * @param ownerDto the owner's mapped DTO, the source of the derived {@code membershipLevel} carried
333	     *                 on the audit trail
334	     */
335	    private void emitOwnerCreatedAudit(Owner owner, OwnerDto ownerDto) {
336	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
337	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
338	            ownerDto.getMembershipLevel());
339	        OwnerCreatedEvent event = new OwnerCreatedEvent(EVENT_SEQ.incrementAndGet(),
340	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
341	        AUDIT.info(event.toJson());
342	    }
