372	    /**
373	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
374	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
375	     * the request body already rejects null and empty values, but permits whitespace-only strings
376	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
377	     * that gap so every required field must carry a non-blank value.
378	     *
379	     * @param ownerFieldsDto the submitted owner fields
380	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
381	     */
382	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
383	        List<String> missing = new ArrayList<>();
384	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
385	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
386	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
387	            missing.add("address");
388	        }
389	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
390	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
391	        if (!missing.isEmpty()) {
392	            throw new InvalidOwnerFieldsException(missing);
393	        }
