424	    /**
425	     * Normalizes the submitted address on create to its canonical form (see
426	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
427	     * stored and returned, and the form every later address comparison (the required-field check,
428	     * household duplicate detection and the shared household id) is judged on. The structured fields
429	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
430	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
431	     * derived from them when a structured {@code addressLine1} is present, falling back to the
432	     * normalized flat {@code address} otherwise. Any absent field is left absent so
433	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
434	     * after normalization likewise reduces to the empty string and is rejected there.
435	     *
436	     * @param ownerFieldsDto the submitted owner fields
437	     */
438	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
439	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
440	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
441	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
442	        ownerFieldsDto.setAddressLine1(addressLine1);
443	        ownerFieldsDto.setAddressLine2(addressLine2);
444	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
445	    }
446	
447	    /**
448	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
449	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
450	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
451	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
452	     * is the single value every later reader of the address (the required-field check, household
453	     * duplicate detection and the shared household id) is judged on.
454	     *
455	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
456	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
457	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
458	     * @return the composed flat address, or {@code null} when no address form was supplied
459	     */
460	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
461	        if (isBlank(addressLine1)) {
462	            return flatAddress;
463	        }
464	        if (isBlank(addressLine2)) {
465	            return addressLine1;
466	        }
467	        return addressLine1 + " " + addressLine2;
468	    }
