470	    /**
471	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
472	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
473	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
474	     * {@code 400 Bad Request}.
475	     *
476	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
477	     *                       {@link #rejectBlankOwnerFields} having already run)
478	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
479	     */
480	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
481	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
482	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
483	        ownerFieldsDto.setTelephone(normalized);
484	    }
