486	    /**
487	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
488	     * untouched (email is optional). When present it is reduced to its canonical form (see
489	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
490	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
491	     *
492	     * @param ownerFieldsDto the submitted owner fields
493	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
494	     *                                     or its domain is on the disposable-domain blocklist
495	     */
496	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
497	        String email = ownerFieldsDto.getEmail();
498	        if (email == null || email.isBlank()) {
499	            return;
500	        }
501	        String normalized = EmailNormalizer.normalize(email)
502	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
503	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
504	            throw new InvalidOwnerFieldsException(List.of("email"));
505	        }
506	        ownerFieldsDto.setEmail(normalized);
507	    }
