509	    /**
510	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
511	     * duplicate detection is now expressed through the single derived {@code identityKey}
512	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
513	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
514	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
515	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
516	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
517	     * carry different telephones have different keys and are both allowed (they are instead recorded as
518	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
519	     * longer makes a duplicate.
520	     *
521	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
522	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
523	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
524	     */
525	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
526	        String identityKey = OwnerIdentity.identityKey(
527	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
528	        boolean inUse = activeOwners().stream()
529	            .map(OwnerIdentity::identityKey)
530	            .anyMatch(identityKey::equals);
531	        if (inUse) {
532	            throw new DuplicateOwnerIdentityException(identityKey);
533	        }
534	    }
