536	    /**
537	     * The owners considered by duplicate detection: every persisted owner except those flagged
538	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
539	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
540	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
541	     * alone. Only owners already persisted (before this create) are included.
542	     *
543	     * @return the non-deleted owners currently persisted
544	     */
545	    private List<Owner> activeOwners() {
546	        return this.clinicService.findAllOwners().stream()
547	            .filter(owner -> !owner.isDeleted())
548	            .toList();
549	    }
