551	    /**
552	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
553	     * both match the submitted values, compared case-insensitively. The count reflects only owners
554	     * already persisted at the time of the create, so the owner being created is never included.
555	     *
556	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
557	     *                  having already run)
558	     * @param lastName  the submitted last name (non-blank here)
559	     * @return the number of existing owners sharing the same first and last name
560	     */
561	    private int countNamesakes(String firstName, String lastName) {
