568	    /**
569	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
570	     * whose stored {@code householdId} equals the value derived for the owner being created. The
571	     * count reflects only owners already persisted at the time of the create, so the owner being
572	     * created is never included; callers add one to obtain the household size after this create.
573	     *
574	     * @param householdId the household identifier derived for the owner being created (see
575	     *                    {@link HouseholdNormalizer#toHouseholdId})
576	     * @return the number of existing owners already sharing that household
577	     */
578	    private int countHouseholdMembers(String householdId) {
579	        return householdMembers(householdId).size();
