582	    /**
583	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
584	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
585	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
586	     * created is never among them.
587	     *
588	     * @param householdId the household identifier derived for the owner being created (see
589	     *                    {@link HouseholdNormalizer#toHouseholdId})
590	     * @return the existing owners already sharing that household (empty when {@code householdId} is
591	     *         {@code null})
592	     */
593	    private List<Owner> householdMembers(String householdId) {
594	        if (householdId == null) {
595	            return List.of();
596	        }
597	        return this.clinicService.findAllOwners().stream()
598	            .filter(member -> householdId.equals(member.getHouseholdId()))
599	            .toList();
600	    }
