602	    /**
603	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
604	     * {@code membershipLevel} among their existing household members. The owner's own level is the
605	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
606	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
607	     * owner's own level is returned unchanged.
608	     *
609	     * @param owner the owner being created, already stamped with its household id and size
610	     * @return the (possibly capped) membership level to stamp on the owner
611	     */
612	    private int cappedMembershipLevel(Owner owner) {
613	        int ownLevel = this.ownerMapper.membershipLevel(owner);
614	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
615	            .mapToInt(this.ownerMapper::membershipLevel)
616	            .max();
617	        return maxHouseholdLevel.isPresent()
618	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
619	            : ownLevel;
620	    }
