650	    /**
651	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
652	     * is none. The create has already cleared the hard-duplicate identity check
653	     * ({@link #rejectDuplicateIdentity}), so its {@code identityKey} matches no existing owner; it is a
654	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code postcode} and
655	     * the {@linkplain Soundex#soundex Soundex} of its {@code lastName} while their identity keys still
656	     * differ. Because the telephone is part of the identity key, two owners with the same last name and
657	     * postcode but different telephones have differing keys and so soft-match here rather than colliding
658	     * as a hard duplicate. The oldest such owner (the earliest persisted) is returned so the flag points
659	     * at the original record; owners with no postcode never match, since a shared postcode is required.
660	     *
661	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
662	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
663	     *         duplicate
664	     */
665	    private Integer findPossibleDuplicate(Owner owner) {
666	        String postcode = owner.getPostcode();
667	        if (postcode == null) {
668	            return null;
669	        }
670	        String identityKey = OwnerIdentity.identityKey(owner);
671	        String lastNameCode = Soundex.soundex(owner.getLastName());
672	        return activeOwners().stream()
673	            .filter(existing -> !identityKey.equals(OwnerIdentity.identityKey(existing)))
674	            .filter(existing -> lastNameCode.equals(Soundex.soundex(existing.getLastName())))
675	            .filter(existing -> postcode.equals(existing.getPostcode()))
676	            .map(Owner::getId)
677	            .filter(Objects::nonNull)
678	            .min(Integer::compareTo)
679	            .orElse(null);
680	    }
