682	    /**
683	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
684	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
685	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
686	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
687	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
688	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
689	     * duplicate, so it is never flagged.
690	     *
691	     * @param owner           the owner being created, with telephone already normalized and
692	     *                        lastName/postcode set
693	     * @param sharesHousehold whether the request opted in to sharing a household
694	     */
695	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
696	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
697	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
698	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
699	    }
700	
701	    /**
702	     * Counts how many existing owners already live in the given city. The submitted city is compared
703	     * case-insensitively against every existing owner's stored city. The result drives both the hard
704	     * capacity rejection (see {@link #rejectCityAtCapacity}) and the {@code capacityWarning} flag.
705	     *
706	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
707	     *             run)
708	     * @return the number of existing owners whose city matches the submitted city
709	     */
710	    private long countOwnersInCity(String city) {
711	        return this.clinicService.findAllOwners().stream()
712	            .map(Owner::getCity)
713	            .filter(Objects::nonNull)
714	            .filter(city::equalsIgnoreCase)
715	            .count();
716	    }
717	
718	    /**
719	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
720	     * A city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
721	     *
722	     * @param city         the submitted city (used only to report the conflict)
723	     * @param ownersInCity the number of owners the city already holds (see {@link #countOwnersInCity})
724	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
725	     */
726	    private void rejectCityAtCapacity(String city, long ownersInCity) {
727	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
728	            throw new OwnerCityAtCapacityException(city);
729	        }
730	    }
731	
732	    /**
733	     * Resolves the effective registration date for a create, rolled onto a business day. The
734	     * supplied date is used when present, otherwise the server's current date; either way the result
735	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
736	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
737	     * stored {@code registrationDate}, the membership number's year segment and the daily
738	     * create-limit's per-day count - is judged on this adjusted date.
739	     *
740	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
741	     *                                 default to the server's current date
742	     * @return the effective registration date, guaranteed to fall on a business day
743	     */
744	    /**
745	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
746	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
747	     * adjustment; a future date cannot describe a registration that has already happened, so it is
748	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
749	     * server's current date) and any date on or before today are accepted.
750	     *
751	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
752	     *                                 omitted
753	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
754	     */
755	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
756	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
757	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
758	        }
759	    }
760	
761	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
762	        LocalDate registrationDate =
763	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
764	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
765	    }
766	
767	    /**
768	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
769	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
770	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
771	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
772	     * Too Many Requests}.
773	     *
774	     * @param registrationDate   the create's effective registration date, already rolled onto a
775	     *                           business day by {@link #effectiveRegistrationDate}
776	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
777	     *                           {@code registrationDate} equals {@code registrationDate}
778	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
779	     *                                              owner registrations
780	     */
781	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
782	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
783	            throw new OwnerDailyRegistrationLimitException(registrationDate);
784	        }
785	    }
786	
787	    /**
788	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
789	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
790	     * bulk-signup warning are judged on.
791	     *
792	     * @param registrationDate the create's effective registration date, already rolled onto a business
793	     *                         day by {@link #effectiveRegistrationDate}
794	     * @return the number of existing owners registered on that day
795	     */
796	    private long countRegisteredOn(LocalDate registrationDate) {
797	        return this.clinicService.findAllOwners().stream()
798	            .map(Owner::getRegistrationDate)
799	            .filter(registrationDate::equals)
800	            .count();
801	    }
802	}
